#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"//extern Gdiplus::Image*  GdiplusImageFile( const char* pszFile );//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  RECT rect;  HGLOBAL hGlobal;  Gdiplus::Image* gdiplusImage;  } Queue_Bitmap;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void ClearBitmap(SQueue& q,void* s)  {  Queue_Bitmap* p = (Queue_Bitmap*)s;  if(p->hGlobal)    ::GlobalFree( p->hGlobal );  if(p->gdiplusImage)    delete p->gdiplusImage;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintBitmap(DefinePaint)  {  QueueP(Queue_Bitmap);  LPBITMAPINFO info = (LPBITMAPINFO)::GlobalLock( p->hGlobal );  if ( info != NULL )    {    LPBYTE bits = (LPBYTE)info;    bits += sizeof( BITMAPINFOHEADER );    if ( info->bmiHeader.biClrImportant > 0 )      bits += info->bmiHeader.biClrImportant*sizeof(COLORREF);    int nMode = ::SetStretchBltMode( hDC, HALFTONE);    ::StretchDIBits( hDC, p->rect.left, p->rect.top,      p->rect.right-p->rect.left,p->rect.bottom-p->rect.top,        0, 0, info->bmiHeader.biWidth, info->bmiHeader.biHeight,          bits, info, DIB_RGB_COLORS,SRCCOPY);    ::SetStretchBltMode( hDC, nMode );    ::GlobalUnlock( p->hGlobal );    }  else  if(p->gdiplusImage)  {    int hh = p->gdiplusImage->GetHeight();    int ww = p->gdiplusImage->GetWidth();    Gdiplus::Graphics Grf( hDC );    Grf.DrawImage ( p->gdiplusImage, p->rect.left, p->rect.top , p->rect.right-p->rect.left, p->rect.bottom-p->rect.top );  }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddBitmap(DefineTegs)  {  //  //HGLOBAL hGlobal = ImageFile( teg[0].value );  //if ( hGlobal == NULL ) return;  //  AddQueueEx(Queue_Bitmap);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintBitmap;  p->clear = &ClearBitmap;  //p->hGlobal = hGlobal;  p->hGlobal = NULL;  p->gdiplusImage = GdiplusImageFile( teg[0].value );  //  STegObj obj[] =    {    { 'R', "rect", &p->rect },    { 'E', "rc"  , &p->rect },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~